 * Faithful ports of the CPython `str` behaviors needed by this project:
 *   - str.splitlines()          -> splitlines()
 *   - repr(str)                 -> strRepr()
 *   - repr() of nested dicts    -> pyRepr()
 *
 * No external dependencies; only built-in JavaScript is used.
 */

// Characters Python's str.splitlines() treats as line boundaries.
// (Code units suffice: every boundary is in the BMP.)
const LINE_BOUNDARIES = new Set([
  '\n', // U+000A LINE FEED
  '\r', // U+000D CARRIAGE RETURN (\r\n counts as ONE boundary)
  '\x0b', // U+000B LINE TABULATION
  '\x0c', // U+000C FORM FEED
  '\x1c', // U+001C FILE SEPARATOR
  '\x1d', // U+001D GROUP SEPARATOR
  '\x1e', // U+001E RECORD SEPARATOR
  '\x85', // U+0085 NEXT LINE
  '\u2028', // U+2028 LINE SEPARATOR
  '\u2029', // U+2029 PARAGRAPH SEPARATOR
]);

/**
 * Port of CPython str.splitlines() (keepends=False).
 */
export function splitlines(s) {
  const lines = [];
  let cur = '';
  let i = 0;
  const n = s.length;
  while (i < n) {
    const ch = s[i];
    if (ch === '\r') {
      lines.push(cur);
      cur = '';
      // "\r\n" is a single line boundary
      i += i + 1 < n && s[i + 1] === '\n' ? 2 : 1;
    } else if (LINE_BOUNDARIES.has(ch)) {
      lines.push(cur);
      cur = '';
      i += 1;
    } else {
      cur += ch;
      i += 1;
    }
  }
  if (cur.length > 0) lines.push(cur);
  return lines;
}

// Python's str.isprintable(): a character is NOT printable when its Unicode
// general category is in group C (Cc, Cf, Cs, Co, Cn) or Z (Zs, Zl, Zp),
// with the single exception of U+0020 SPACE.
const NON_PRINTABLE = /[\p{C}\p{Z}]/u;

function isPrintable(codePoint) {
  if (codePoint === 0x20) return true;
  return !NON_PRINTABLE.test(String.fromCodePoint(codePoint));
}

/**
 * Port of CPython repr() for str.
 * Quote selection: single quotes, unless the string contains a single quote
 * and no double quote, in which case double quotes are used.
 */
export function strRepr(s) {
  let quote = "'";
  if (s.includes("'") && !s.includes('"')) quote = '"';
  let out = quote;
  for (const ch of s) { // iterates by Unicode code point
    const cp = ch.codePointAt(0);
    if (ch === '\\') {
      out += '\\\\';
    } else if (ch === quote) {
      out += '\\' + quote;
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (ch === '\t') {
      out += '\\t';
    } else if (isPrintable(cp)) {
      out += ch;
    } else if (cp < 0x100) {
      out += '\\x' + cp.toString(16).padStart(2, '0');
    } else if (cp < 0x10000) {
      out += '\\u' + cp.toString(16).padStart(4, '0');
    } else {
      out += '\\U' + cp.toString(16).padStart(8, '0');
    }
  }
  return out + quote;
