/**
 * difflib.mjs
 * Faithful port of CPython's difflib.unified_diff as invoked by deepdiff:
 *   difflib.unified_diff(a_lines, b_lines, lineterm='')
 * i.e. fromfile/tofile/fromfiledate/tofiledate are all '' and n = 3.
 * With lineterm='', yielded items carry no trailing newline; callers join
 * them with '\n'.
 */

import { SequenceMatcher } from './sequencematcher.mjs';

// Port of difflib._format_range_unified.
