/**
 * deepdiff.mjs
 * Black-box reimplementation of the observable behavior of
 * deepdiff.DeepDiff(t1, t2) for the case where both t1 and t2 are strings
 * (which is all this program can produce, since argparse reads them as str).
 *
 * Observed contract (verified against the reference behavior):
 *   - t1 == t2                     -> {} (empty result)
 *   - t1 != t2                     -> {'values_changed': {'root':
 *                                       {'new_value': t2, 'old_value': t1}}}
 *   - additionally, when at least one of the strings contains '\n', a
 *     unified diff over str.splitlines() of both sides is computed; if it
 *     is non-empty it is stored under the 'diff' key (after 'old_value').
 *
 * The result is an ordered Map tree so that pyRepr() renders it with
 * Python's dict repr, key order and str repr semantics.
 */

import { splitlines } from './pystr.mjs';
import { unifiedDiffText } from './difflib.mjs';

/**
 * Returns a Map tree representing the DeepDiff result for two strings.
 */
export function deepDiffStrings(t1, t2) {
  const result = new Map();
  if (t1 === t2) return result;

  const root = new Map();
  root.set('new_value', t2);
  root.set('old_value', t1);

  if (t1.includes('\n') || t2.includes('\n')) {
    const diff = unifiedDiffText(splitlines(t1), splitlines(t2));
    if (diff.length > 0) root.set('diff', diff);
  }

  result.set('values_changed', new Map([['root', root]]));
  return result;
}

