/**
 * argparse.mjs
 * Black-box reimplementation of the argparse behavior of:
 *
 *   parser = argparse.ArgumentParser()
 *   parser.add_argument('--a', type=str, required=True)
 *   parser.add_argument('--b', type=str, required=True)
 *   args = parser.parse_args()
 *
 * Reproduced semantics (verified against the reference behavior):
 *   - `--a VALUE` and `--a=VALUE` forms; unambiguous long-option prefixes
 *     (argparse's allow_abbrev), e.g. `--he` -> `--help`;
 *   - the token following an option is its value unless it "looks like an
 *     option string" (starts with '-', except '-', negative numbers like
 *     -5 / -1.5, and tokens containing a space);
 *   - `-h` / `--help` print help to stdout and exit 0;
 *   - a repeated option keeps the last value;
 *   - `--` stops option parsing; remaining tokens become extras;
 *   - missing required options: error listing them in definition order
 *     (checked BEFORE unrecognized arguments), exit code 2;
 *   - unknown options / stray positionals: `unrecognized arguments: ...`,
 *     exit code 2;
 *   - prog name is basename(argv[1]), like argparse's basename(sys.argv[0]).
 *
 * Only Node.js built-ins are used.
 */

import { basename } from 'node:path';

const LONG_OPTIONS = ['--help', '--a', '--b'];

// argparse._negative_number_matcher; with no number-like options registered,
// tokens matching this are treated as values, not option strings.
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function looksLikeOptionString(token) {
  if (!token.startsWith('-')) return false;
  if (token === '-') return false; // a bare '-' is a value
  if (NEGATIVE_NUMBER.test(token)) return false;
  if (token.includes(' ')) return false; // tokens with spaces are values
  return true;
}

function usageLine(prog) {
  return `usage: ${prog} [-h] --a A --b B`;
}

function printHelpAndExit(prog) {
  const text =
    usageLine(prog) +
    '\n' +
    '\n' +
    'options:\n' +
    '  -h, --help  show this help message and exit\n' +
    '  --a A\n' +
    '  --b B\n';
  process.stdout.write(text);
  process.exit(0);
}

function errorAndExit(prog, message) {
  process.stderr.write(usageLine(prog) + '\n');
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

/**
 * Parses argv (typically process.argv.slice(2)) and returns { a, b }.
 * Exits the process with argparse-compatible output on -h/error.
 */
export function parseArgs(argv, prog = basename(process.argv[1] || '')) {
  const values = { a: undefined, b: undefined };
  const seen = new Set();
  const extras = [];
  let optionsEnded = false;

  let i = 0;
  while (i < argv.length) {
    const token = argv[i];

    if (optionsEnded) {
      extras.push(token);
      i += 1;
      continue;
    }
    if (token === '--') {
      optionsEnded = true;
      i += 1;
      continue;
    }
    if (token === '-h') {
      printHelpAndExit(prog);
    }
    if (token.startsWith('--')) {
      let name = token;
      let explicitValue;
      const eq = token.indexOf('=');
      if (eq !== -1) {
        name = token.slice(0, eq);
        explicitValue = token.slice(eq + 1);
      }

      let resolved = null;
      if (LONG_OPTIONS.includes(name)) {
        resolved = name;
      } else {
        const matches = LONG_OPTIONS.filter((opt) => opt.startsWith(name));
        if (matches.length === 1) {
          resolved = matches[0];
        } else if (matches.length > 1) {
          errorAndExit(prog, `ambiguous option: ${name} could match ${matches.join(', ')}`);
        }
      }

      if (resolved === null) {
        // Unknown long option: collected, reported at the end.
        extras.push(token);
        i += 1;
        continue;
      }
      if (resolved === '--help') {
        printHelpAndExit(prog);
      }

      const key = resolved.slice(2); // '--a' -> 'a'
      if (explicitValue !== undefined) {
        values[key] = explicitValue;
        seen.add(key);
        i += 1;
        continue;
      }
      const next = argv[i + 1];
      if (next === undefined || looksLikeOptionString(next)) {
        errorAndExit(prog, `argument ${resolved}: expected one argument`);
      }
      values[key] = next;
      seen.add(key);
      i += 2;
      continue;
    }
    if (looksLikeOptionString(token)) {
      // Unknown short option (e.g. '-x'): collected as an extra.
      extras.push(token);
      i += 1;
      continue;
    }
    // Plain value with no positional defined: extra.
    extras.push(token);
    i += 1;
  }

  // argparse checks required arguments before reporting unrecognized ones.
  const missing = [];
  if (!seen.has('a')) missing.push('--a');
  if (!seen.has('b')) missing.push('--b');
  if (missing.length > 0) {
    errorAndExit(prog, `the following arguments are required: ${missing.join(', ')}`);
  }
  if (extras.length > 0) {
    errorAndExit(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return values;
}

