import { execFileSync } from 'node:child_process';

const EXE = '/workspace/dataset/test1_executable';
const JS = '/output/test1.mjs';

function run(cmd, args) {
  try {
    const out = execFileSync(cmd[0], [...cmd.slice(1), ...args], { encoding: 'utf-8', stdio: ['pipe', 'pipe', 'pipe'] });
    return { code: 0, out };
  } catch (e) {
    return { code: e.status, out: (e.stdout ?? '') + '\x00STDERR\x00' + (e.stderr ?? '') };
  }
}

function check(a, b, label) {
  const r1 = run([EXE], ['--a', a, '--b', b]);
  const r2 = run(['node', JS], ['--a', a, '--b', b]);
  if (r1.out !== r2.out || r1.code !== r2.code) {
    console.log(`MISMATCH [${label}]`);
    console.log('  a =', JSON.stringify(a).slice(0, 200));
    console.log('  b =', JSON.stringify(b).slice(0, 200));
    console.log('  py :', JSON.stringify(r1.out).slice(0, 400), 'code', r1.code);
    console.log('  js :', JSON.stringify(r2.out).slice(0, 400), 'code', r2.code);
    return false;
  }
  return true;
}

let ok = 0, bad = 0;
const T = (a, b, l) => { check(a, b, l) ? ok++ : bad++; };

// Directed cases
T('hello', 'world', 'basic');
T('same', 'same', 'equal');
T('', '', 'empty');
T('', 'x', 'empty-vs-x');
T("it's", 'say "hi"', 'quotes');
T('both\'and"', 'both\'and"!', 'both-quotes');
T('line1\nline2', 'line1\nline3', 'multiline');
T('x', 'x\n', 'trailing-nl');
T('x\ny', 'x\ny\n', 'trailing-nl2');
T('a\n', 'a\n\n', 'extra-blank');
T('a\rb', 'a\rb\r', 'cr-only');
T('a\vb', 'a\vc', 'vtab');
T('a\x0cb', 'a\x0cb\x0c', 'formfeed');
T('a\x1cb\x1dc\x1ed', 'a\x1cb\x1dc\x1ee', 'file-seps');
T('a\x85b', 'a\x85c', 'nel');
T('a\u2028b', 'a\u2028b\u2029', 'u2028');
T('héllo→世界', 'héllo→世畀', 'unicode');
T('😀😃😄', '😀😃😅', 'emoji');
T('nbsp x', 'nbsp x', 'nbsp');
T('\ttab', '\x07bell', 'ctrl');
T('q\\w', 'q\\\\w', 'backslash');
T('a'.repeat(1000), 'a'.repeat(999) + 'b', 'long-1line');
T(Array.from({length: 300}, (_, i) => i + 1).join('\n'),
  Array.from({length: 300}, (_, i) => (i + 1 === 150 ? 'CHANGED' : i + 1)).join('\n'), '300-lines');
// autojunk: >200 lines with one very popular line
T(Array.from({length: 250}, () => 'pop').join('\n') + '\nuniqueA',
  Array.from({length: 250}, () => 'pop').join('\n') + '\nuniqueB', 'autojunk-tail');
T('x\n' + Array.from({length: 250}, () => 'pop').join('\n'),
  'y\n' + Array.from({length: 250}, () => 'pop').join('\n'), 'autojunk-head');

// Random fuzz
const alphabet = ['a', 'b', 'c', '\n', '\r', '\t', "'", '"', '\\', 'é', '😀', '\x07', ' ', ' ', '\x0b', '\u2028', 'x'.repeat(30)];
function rnd(n) { return Math.floor(Math.random() * n); }
let seed = 12345;
function srand() { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; }
for (let t = 0; t < 400; t++) {
  const mk = () => {
    const len = Math.floor(srand() * 40);
    let s = '';
    for (let k = 0; k < len; k++) s += alphabet[Math.floor(srand() * alphabet.length)];
    return s;
  };
  T(mk(), mk(), `fuzz-${t}`);
}
// Fuzz with many lines (exercise grouped opcodes + autojunk)
const words = ['alpha', 'beta', 'gamma', 'delta', 'pop', 'x', ''];
for (let t = 0; t < 120; t++) {
  const mk = () => {
    const n = Math.floor(srand() * 320);
    const lines = [];
    for (let k = 0; k < n; k++) lines.push(words[Math.floor(srand() * words.length)]);
    return lines.join('\n');
  };
  T(mk(), mk(), `lines-fuzz-${t}`);
}

console.log(`\n${ok} passed, ${bad} mismatched`);
process.exit(bad ? 1 : 0);

