import("node:child_process").then(({execFileSync}) => {
  const cases = [
    ["hello","world"],["same","same"],["",""],["","x"],
    ["line1\nline2","line1\nline3"],["x","x\n"],
    ["a\rb","a\rb\r"],["a\x85b","a\x85c"],["héllo→世界","héllo→世畀"],
    ["😀😃😄","😀😃😅"],["nbsp x","nbsp x"],["\ttab","\x07bell"],
    ["q\\w","q\\\\w"],["only1","two\nlines"],["a\n","a\n\n"],
  ];
  let bad = 0;
  for (const [a,b] of cases) {
    const py = execFileSync("/workspace/dataset/test1_executable", ["--a",a,"--b",b], {encoding:"utf8"});
    const js = execFileSync("node", ["/output/test1.mjs","--a",a,"--b",b], {encoding:"utf8"});
    if (py !== js) { bad++; console.log("MISMATCH", JSON.stringify(a), JSON.stringify(b)); console.log("py:",JSON.stringify(py)); console.log("js:",JSON.stringify(js)); }
  }
  console.log(bad ? bad+" mismatches" : "all "+cases.length+" quick cases OK");
});'

